function selectParser(contentType, parsers) {
  if (parsers[contentType] !== undefined) return parsers[contentType]
  return resolveParser(contentType, parsers)
}
function resolveParser(contentType, parsers) {
  if (parsers[contentType] !== undefined) return parsers[contentType]
  const mediaType = contentType.split(';')[0].trim()
  return parsers[mediaType] !== undefined ? parsers[mediaType] : parsers['*']
}
